-- Verify (run after applying):
--   select site_domain, count(*) from public.vertical_sites group by 1 order by 1;
--   -- expect: giniloh.com 21 | wellroost.com 5
--
--   select count(*) from public.vertical_sites;  -- expect 26
--
-- Coverage is enforced in CI-style by scripts/check_vertical_sites.py, which fails if any
-- vertical in context/verticals.json has no row here (and vice versa).
